fn solve(n: i8) -> bool {
    // Assumed: 1 <= n <= 99

    if n < 12 {
        return !matches!(n, 1 | 7 | 9 | 10 | 11);
    }

    if n > 12 && n < 30 {
        return false;
    }

    if n > 69 && n < 80 {
        return false;
    }

    if n > 89 {
        return false;
    }

    // Remaining values are: 12, 30..=69, 80..=89
    let last_digit = n % 10; // non-negative since n is positive
    !matches!(last_digit, 1 | 7 | 9)
}